  3	namespace Modules\AI\Domain\Decision;
  4	
  5	use Modules\AI\Models\AiProfile;
  6	use OGame\Factories\PlayerServiceFactory;
  7	use OGame\GameMissions\ColonisationMission;
  8	use OGame\GameMissions\EspionageMission;
  9	use OGame\GameMissions\ExpeditionMission;
 10	use OGame\GameObjects\Models\UnitObject;
 11	use OGame\Models\FleetMission;
 12	use OGame\Models\User;
 13	use OGame\Services\ObjectService;
 14	use OGame\Services\PlanetService;
 15	use OGame\Services\PlayerService;
 16	
 17	/**
 18	 * Answers whether this account can dispatch an expedition now.
 19	 *
 20	 * An expedition is the host's slot-16 mission; the module only adds the
 21	 * feasibility the host itself would refuse — Astrophysics researched, a free
 22	 * expedition slot, and a disposable cargo ship on some own body. The fleet is
 23	 * never the account's whole stock (EXP-001): the dispatch sends one small
 24	 * civil ship.
 25	 */
 26	class QueueableExpeditionPlanner
 27	{
 28	    /** Slot 16 is the only coordinate the host's expedition mission accepts. */
 29	    private const EXPEDITION_POSITION = 16;
 30	
 31	    /** The window over which a system's outgoing expedition load is counted for rotation. */
 32	    private const ROTATION_WINDOW_HOURS = 24;
 33	
 34	    public function __construct(
 35	        private PlayerServiceFactory $playerServiceFactory,
 36	    ) {
 37	    }
 38	
 39	    public function plan(int $playerId): ?QueueableExpedition
 40	    {
 41	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 42	        if ($profile === null) {
 43	            return null;
 44	        }
 45	
 46	        if (!User::query()->whereKey($playerId)->exists()) {
 47	            return null;
 48	        }
 49	
 50	        $player = $this->playerServiceFactory->make($playerId, true);
 51	
 52	        // The host requires Astrophysics before any expedition, and refuses a
 53	        // dispatch when every slot is already out.
 54	        if ($player->getResearchLevel('astrophysics') <= 0) {
 55	            return null;
 56	        }
 57	        if ($player->getExpeditionSlotsInUse() >= $player->getExpeditionSlotsMax()) {
 58	            return null;
 59	        }
 60	
 61	        $origin = $this->origin($player);
 62	        if ($origin === null) {
 63	            return null;
 64	        }
 65	
 66	        $coordinates = $origin->getPlanetCoordinates();
 67	
 68	        return app()->makeWith(QueueableExpedition::class, [
 69	            'planetId' => $origin->getPlanetId(),
 70	            'galaxy' => (int) $coordinates->galaxy,
 71	            'system' => (int) $coordinates->system,
 72	            'position' => self::EXPEDITION_POSITION,
 73	        ]);
 74	    }
 75	
 76	    /**
 77	     * The disposable cargo ship this body can send, or null when it has none.
 78	     *
 79	     * The expedition fleet is a civil ship with cargo space — the smallest one,
 80	     * so it is the cheapest to lose to the host's black-hole outcome (EXP-001).
 81	     * The probe and the colony ship are excluded by the host's own mission
 82	     * vocabulary; military hulls are the fleet the account depends on.
 83	     * ponytail: the fleet is fixed at one hull; a persona band that varies the
 84	     * count by skill band is the upgrade path once the executor is observed.
 85	     */
 86	    public function disposableShip(PlayerService $player, PlanetService $planet): ?UnitObject
 87	    {
 88	        $civilMachines = array_map(
 89	            static fn (UnitObject $ship): string => $ship->machine_name,
 90	            ObjectService::getCivilShipObjects(),
 91	        );
 92	        $probe = EspionageMission::getRequiredShipMachineNames()[0];
 93	        $colonyShip = ColonisationMission::getRequiredShipMachineNames()[0];
 94	
 95	        $smallest = null;
 96	        foreach ($planet->getShipUnits()->units as $entry) {
 97	            $machine = $entry->unitObject->machine_name;
 98	            if (!in_array($machine, $civilMachines, true) || $machine === $probe || $machine === $colonyShip) {
 99	                continue;
100	            }
101	
102	            $capacity = $entry->unitObject->properties->capacity->calculate($player)->totalValue;
103	            if ($capacity <= 0) {
104	                continue;
105	            }
106	
107	            if ($smallest === null || $capacity < $smallest['capacity']) {
108	                $smallest = ['ship' => $entry->unitObject, 'capacity' => $capacity];
109	            }
110	        }
111	
112	        return $smallest['ship'] ?? null;
113	    }
114	
115	    /**
116	     * The strongest combat hull this body owns, by the host's attack value: the
117	     * escort that survives a pirate (EXP-002).
118	     */
119	    public function combatHull(PlayerService $player, PlanetService $planet): ?UnitObject
120	    {
121	        return $this->bestOwned($player, $planet, ObjectService::getMilitaryShipObjects(), 'attack');
122	    }
123	
124	    /**
125	     * The fastest civil hull this body owns, by the host's speed value: the
126	     * pathfinder that shortens the trip (EXP-002). The probe and the colony ship
127	     * are excluded by the host's own mission vocabulary.
128	     */
129	    public function fastestCivilHull(PlayerService $player, PlanetService $planet): ?UnitObject
130	    {
131	        return $this->bestOwned(
132	            $player,
133	            $planet,
134	            ObjectService::getCivilShipObjects(),
135	            'speed',
136	            [...EspionageMission::getRequiredShipMachineNames(), ...ColonisationMission::getRequiredShipMachineNames()],
137	        );
138	    }
139	
140	    /**
141	     * The best-owned hull for a role, by the host's own stat. Only hulls the
142	     * body actually holds are candidates; the role is never a machine name.
143	     *
144	     * @param array<UnitObject> $objects
145	     * @param 'attack'|'speed' $property
146	     * @param list<string> $exclude
147	     */
148	    private function bestOwned(PlayerService $player, PlanetService $planet, array $objects, string $property, array $exclude = []): ?UnitObject
149	    {
150	        $owned = $planet->getShipUnits()->toArray();
151	
152	        $best = null;
153	        $bestValue = -1.0;
154	        foreach ($objects as $object) {
155	            if (in_array($object->machine_name, $exclude, true) || ($owned[$object->machine_name] ?? 0) <= 0) {
156	                continue;
157	            }
158	
159	            $value = $object->properties->{$property}->calculate($player)->totalValue;
160	            if ($value > $bestValue) {
161	                $best = $object;
162	                $bestValue = $value;
163	            }
164	        }
165	
166	        return $best;
167	    }
168	
169	    /**
170	     * The own body whose system has sent the fewest recent expeditions, so the
171	     * account spreads expeditions across its systems instead of hammering one
172	     * (EXP-003). The rotation falls out of the count; no hard threshold is named.
173	     */
174	    private function origin(PlayerService $player): ?PlanetService
175	    {
176	        $recent = $this->recentExpeditionsBySystem($player->getId());
177	
178	        $best = null;
179	        foreach ($player->planets->all() as $planet) {
180	            if ($this->disposableShip($player, $planet) === null) {
181	                continue;
182	            }
183	
184	            $coordinates = $planet->getPlanetCoordinates();
185	            $count = $recent["{$coordinates->galaxy}:{$coordinates->system}"] ?? 0;
186	
187	            if ($best === null || $count < $best['count']) {
188	                $best = ['planet' => $planet, 'count' => $count];
189	            }
190	        }
191	
192	        return $best['planet'] ?? null;
