 11	use OGame\Models\Planet;
 12	use OGame\Models\Planet\Coordinate;
 13	use OGame\Models\User;
 14	use OGame\Services\PlanetService;
 15	use OGame\Services\PlayerService;
 16	use OGame\Services\SettingsService;
 17	
 18	/**
 19	 * Answers whether this account can colonise now, and where.
 20	 *
 21	 * The chain the whole expansion rests on: an account with one homeworld has
 22	 * nowhere to fleetsave, transport or spread, so a colony is the prerequisite for
 23	 * every later fleet behaviour. Nothing here names a slot, a galaxy or a position
 24	 * bonus -- the empty slot is whatever coordinate the host reports as unoccupied,
 25	 * the reach is the account's own astrophysics answer (`canColonizePosition`), and
 26	 * the order is a deterministic per-account walk so a cohort does not all converge
 27	 * on the same first slot.
 28	 *
 29	 * The scan is bounded: an empty slot near the account's seeded start is taken,
 30	 * and the pass stops after a fixed number of checks rather than walking the
 31	 * universe.
 32	 */
 33	class QueueableColonyPlanner
 34	{
 35	    /** Hard ceiling on coordinate checks per decision, so a full universe can never stall a session. */
 36	    private const MAX_SCANS = 600;
 37	
 38	    public function __construct(
 39	        private PlayerServiceFactory $playerServiceFactory,
 40	        private PlanetServiceFactory $planetServiceFactory,
 41	        private SettingsService $settings,
 42	    ) {
 43	    }
 44	
 45	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableColony
 46	    {
 47	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 48	        if ($profile === null) {
 49	            return null;
 50	        }
 51	
 52	        if (!User::query()->whereKey($playerId)->exists()) {
 53	            return null;
 54	        }
 55	
 56	        $player ??= $this->playerServiceFactory->make($playerId, true);
 57	
 58	        // An account at its planet cap cannot found another colony: the host cancels the
 59	        // mission at arrival, so planning one is pure waste of a colony ship and a fleet slot.
 60	        // The cap is the host's own astrophysics answer, never a module constant.
 61	        if ($player->planets->planetCount() >= $player->getMaxPlanetAmount()) {
 62	            return null;
 63	        }
 64	
 65	        $origin = $this->originPlanet($player->planets->all());
 66	        if ($origin === null) {
 67	            return null;
 68	        }
 69	
 70	        $target = $this->emptySlot($player, $profile->random_seed);
 71	        if ($target === null) {
 72	            return null;
 73	        }
 74	
 75	        return app()->makeWith(QueueableColony::class, [
 76	            'planetId' => $origin->getPlanetId(),
 77	            'galaxy' => $target->galaxy,
 78	            'system' => $target->system,
 79	            'position' => $target->position,
 80	            'missionType' => ColonisationMission::getTypeId(),
 81	        ]);
 82	    }
 83	
 84	    /**
 85	     * The planet a colony leaves from: the one holding a colony ship, else the account's first.
 86	     *
 87	     * Waiting for the ship before committing to a free slot is what left the cohort never
 88	     * colonising: the slot is claimed by deciding to settle it, and the ship a shipyard builds
 89	     * for that decision belongs to the same decision rather than to its precondition. The host
 90	     * still owns the ship's machine name and the reach of the walk.
 91	     *
 92	     * @param array<int, PlanetService> $planets
 93	     */
 94	    private function originPlanet(array $planets): ?PlanetService
 95	    {
 96	        $ship = ColonisationMission::getRequiredShipMachineNames()[0];
 97	
 98	        foreach ($planets as $planet) {
 99	            if ($planet->getShipUnits()->getAmountByMachineName($ship) > 0) {
100	                return $planet;
101	            }
102	        }
103	
104	        $first = array_key_first($planets);
105	
106	        return $first === null ? null : $planets[$first];
107	    }
108	
109	    /**
110	     * The largest empty, colonisable coordinate from a seeded start, bounded.
111	     *
112	     * An experienced player colonises the bigger slots, not the first empty one:
113	     * the host's own field range for each position is the planet's size, so the
114	     * walk keeps the largest empty slot it sees and returns it. The per-account
115	     * seed offsets the walk so two accounts do not claim the same slot, and it
116	     * stays the tie-break: an equal-size slot later in the walk loses. The host
117	     * answers reach (`canColonizePosition`) and emptiness (one read of the rows
118	     * occupying the systems the walk visits); the field range is the host's
119	     * `planetData`, never a position list.
120	     */
121	    private function emptySlot(PlayerService $player, int $seed): ?Coordinate
122	    {
123	        $galaxies = max(1, $this->settings->numberOfGalaxies());
124	        $systems = max(1, $this->settings->numberOfSystems());
125	        // The walk is bounded by systems rather than by a running counter: one
126	        // comparison caps the whole decision at MAX_SCANS coordinates, so a full
127	        // universe cannot stall a session and the bound never needs a per-check
128	        // branch.
129	        $systemsPerGalaxy = min($systems, max(1, intdiv(self::MAX_SCANS, 12 * $galaxies)));
130	
131	        $best = null;
132	        $bestFields = -1.0;
133	
134	        for ($galaxyOffset = 0; $galaxyOffset < $galaxies; $galaxyOffset++) {
135	            $galaxy = 1 + (($seed + $galaxyOffset) % $galaxies);
136	
137	            $systemsInWalk = [];
138	            for ($system = 1; $system <= $systemsPerGalaxy; $system++) {
139	                $systemsInWalk[] = 1 + (($system + ($seed >> 4) - 1) % $systems);
140	            }
141	
142	            // The walk asks about every position of every system it visits, and a
143	            // point lookup per position costs a round trip each for an answer one
144	            // read already holds. `destroyed` is deliberately unfiltered: a row
145	            // occupies its coordinate exactly as the host reports it.
146	            $occupied = [];
147	            foreach (Planet::query()
148	                ->where('galaxy', $galaxy)
149	                ->whereIn('system', $systemsInWalk)
150	                ->where('planet_type', PlanetType::Planet->value)
151	                ->get(['system', 'planet']) as $occupying) {
152	                $occupied[$occupying->system . ':' . $occupying->planet] = true;
153	            }
154	
155	            foreach ($systemsInWalk as $systemWithOffset) {
156	                for ($position = UniverseConstants::MIN_PLANET_POSITION; $position <= UniverseConstants::MAX_PLANET_POSITION; $position++) {
157	                    if (!$player->canColonizePosition($position)) {
158	                        continue;
159	                    }
160	
161	                    if (isset($occupied[$systemWithOffset . ':' . $position])) {
162	                        continue;
163	                    }
164	
165	                    // The size a planet at this position would get, from the host's
166	                    // own field range (mid positions report the widest range). The
167	                    // largest empty slot seen so far wins; strict > keeps the
168	                    // seeded walk order as the tie-break.
169	                    $fields = $this->planetServiceFactory->planetData($position, false)['fields'][1];
170	                    if ($fields > $bestFields) {
171	                        $best = new Coordinate($galaxy, $systemWithOffset, $position);
172	                        $bestFields = (float) $fields;
173	                    }
174	                }
175	            }
176	        }
177	
178	        return $best;
179	    }
180	}

